// STEP 2 - STRICT FILTER. Nothing leaves this node unless it matches one of your enabled rules.
// (Generated from server/filter/matchEmails.js - do not edit by hand.)
const body = $('Webhook').first().json.body || {};
const OFFSET = Number(body.utcOffsetMinutes) || 0; // your timezone, so "whole days" match your own day
const rules = Array.isArray(body.rules) ? body.rules : [];

// The strict filter. Pure and deterministic: same emails + same rules = same
// result, no AI, no randomness. It only ever returns emails that satisfy at
// least one enabled rule, and it fails closed on anything it doesn't understand.
const norm = (s) => String(s ?? "").trim().toLowerCase();
const domainOf = (addr) => norm(addr).split("@").pop();

// Dates are whole days in the server's local time (your own timezone).
const startOfDay = (d) => Date.parse(`${d}T00:00:00Z`) - OFFSET * 60000;
const endOfDay = (d) => Date.parse(`${d}T23:59:59.999Z`) - OFFSET * 60000;

const tests = {
  sender_email: { equals: (e, v) => norm(e.from.email) === v },
  sender_name: {
    contains: (e, v) => norm(e.from.name).includes(v),
    equals: (e, v) => norm(e.from.name) === v,
  },
  sender_domain: { equals: (e, v) => domainOf(e.from.email) === v },
  subject: {
    contains: (e, v) => norm(e.subject).includes(v),
    equals: (e, v) => norm(e.subject) === v,
  },
  keyword: { contains: (e, v) => norm(e.subject).includes(v) || norm(e.body).includes(v) },
  received_date: {
    on_or_after: (e, v) => new Date(e.receivedAt).getTime() >= startOfDay(v),
    on_or_before: (e, v) => new Date(e.receivedAt).getTime() <= endOfDay(v),
  },
};

function matchesCondition(email, { field, op, value }) {
  const test = tests[field]?.[op];
  const v = field === "received_date" ? String(value ?? "").trim() : norm(value);
  if (!test || !v) return false; // unknown or empty condition never matches
  return test(email, v);
}

function matchesRule(email, rule) {
  if (!rule.enabled || !Array.isArray(rule.conditions) || rule.conditions.length === 0) return false;
  const check = (c) => matchesCondition(email, c);
  return rule.operator === "OR" ? rule.conditions.some(check) : rule.conditions.every(check);
}

/** Rules that are allowed to select emails at all. */
const activeRules = (rules) =>
  rules.filter((r) => r.enabled && Array.isArray(r.conditions) && r.conditions.length > 0);

/**
 * Returns [{ email, matchedRules: [names] }], newest first.
 * An email appears if ANY enabled rule matches it. Nothing else is ever added.
 */
function matchEmails(emails, rules) {
  const active = activeRules(rules);
  const out = [];
  for (const email of emails) {
    const names = active.filter((r) => matchesRule(email, r)).map((r) => r.name);
    if (names.length) out.push({ email, matchedRules: names });
  }
  return out.sort((a, b) => new Date(b.email.receivedAt) - new Date(a.email.receivedAt));
}

// ---- turn whatever shape the Gmail node returns into one simple shape ----
const stripHtml = (h) => String(h).replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi, " ").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
const b64 = (s) => Buffer.from(String(s).replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8");
const partText = (p, mime) => {
  if (!p) return "";
  if (p.mimeType === mime && p.body && p.body.data) return b64(p.body.data);
  for (const c of p.parts || []) { const t = partText(c, mime); if (t) return t; }
  return "";
};
const header = (item, name) => {
  const list = (item.payload && item.payload.headers) || (Array.isArray(item.headers) ? item.headers : null);
  if (list) { const h = list.find((x) => String(x.name).toLowerCase() === name); if (h) return h.value; }
  if (item.headers && typeof item.headers === "object" && !Array.isArray(item.headers)) {
    const k = Object.keys(item.headers).find((k) => k.toLowerCase() === name);
    if (k) return item.headers[k];
  }
  return undefined;
};
const parseAddress = (v) => {
  if (!v) return null;
  if (Array.isArray(v)) return parseAddress(v[0]);
  if (typeof v === "string") {
    const m = v.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
    if (m) return { name: m[1].trim() || m[2].trim(), email: m[2].trim() };
    return v.includes("@") ? { name: v.trim(), email: v.trim() } : null;
  }
  if (v.value) return parseAddress(v.value);
  if (v.address) return { name: v.name || v.address, email: v.address };
  if (v.text) return parseAddress(v.text);
  return null;
};
const normalize = (item) => {
  const from = parseAddress(item.from ?? item.From ?? header(item, "from"));
  const subject = item.subject ?? item.Subject ?? header(item, "subject") ?? "";
  const dateRaw = item.internalDate ? Number(item.internalDate) : (item.date ?? item.Date ?? header(item, "date"));
  const when = new Date(dateRaw);
  if (!from || Number.isNaN(when.getTime())) return null;
  const text = item.text || item.textPlain || partText(item.payload, "text/plain")
    || stripHtml(item.html || item.textHtml || partText(item.payload, "text/html")) || item.snippet || "";
  return { id: String(item.id), from, subject: String(subject), receivedAt: when.toISOString(), body: String(text) };
};

const raw = $input.all().map((i) => i.json).filter((j) => j && j.id); // an empty inbox gives no ids
const parsed = [];
let skipped = 0;
for (const item of raw) { const e = normalize(item); if (e) parsed.push(e); else skipped++; }

const matches = matchEmails(parsed, rules);
return [{ json: {
  emails: matches.map((m) => m.email),
  meta: { fetched: raw.length, matched: matches.length, skipped, sampleKeys: Object.keys(raw[0] || {}).slice(0, 12) },
} }];
